import React, { useEffect, useState } from 'react';
import './App.css';

type Slide = {
  id: number;
  title: string;
  imageUrl: string;
};

const SLIDES: Slide[] = [
  {
    id: 1,
    title: 'Snowflakes glowing under city lights',
    imageUrl: 'https://picsum.photos/seed/slide-1/800/400'
  },
  {
    id: 2,
    title: 'Forest trail in the morning',
    imageUrl: 'https://images.pexels.com/photos/1563604/pexels-photo-1563604.jpeg'
  },
  {
    id: 3,
    title: 'City lights at night',
    imageUrl: 'https://images.pexels.com/photos/220067/pexels-photo-220067.jpeg'
  }
];

const AUTOPLAY_MS = 1000;

export default function App() {
  const [slides, setSlides] = useState(SLIDES);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [playRequested, setPlayRequested] = useState(false);

  const totalSlides = slides.length;
  const currentSlide = slides[currentIndex] ?? null;

  const canGoPrev = currentIndex > 0;
  const canGoNext = currentIndex < totalSlides - 1;
  const canPlay = totalSlides >= 2;
  const isPlaying = playRequested && canPlay;

  // The index is a dependency, so any move, by the timer or the user, restarts the wait.
  useEffect(() => {
    if (!isPlaying) return;
    const timer = window.setTimeout(() => {
      setCurrentIndex((index) => (index + 1) % totalSlides);
    }, AUTOPLAY_MS);
    return () => window.clearTimeout(timer);
  }, [isPlaying, currentIndex, totalSlides]);

  const goTo = (index: number) => {
    if (index < 0 || index >= totalSlides) return;
    setCurrentIndex(index);
  };

  const prev = () => {
    if (canGoPrev) goTo(currentIndex - 1);
  };

  const next = () => {
    if (canGoNext) goTo(currentIndex + 1);
  };

  const removeCurrent = () => {
    setSlides((current) => current.filter((_, index) => index !== currentIndex));
    setCurrentIndex(Math.max(0, Math.min(currentIndex, totalSlides - 2)));
  };

  const onKeyDown = (event: React.KeyboardEvent<HTMLElement>) => {
    if (event.key === 'ArrowRight') next();
    else if (event.key === 'ArrowLeft') prev();
    else if (event.key === 'Home') goTo(0);
    else if (event.key === 'End') goTo(totalSlides - 1);
    else return;
    event.preventDefault();
  };

  return (
    <main className="main">
      <section
        className="section"
        role="region"
        aria-roledescription="carousel"
        aria-label="Image slider"
        tabIndex={0}
        onKeyDown={onKeyDown}
      >
        <h1>Image Slider</h1>

        {currentSlide ? (
          <div className="slider-body">
            <figure className="frame">
              <img
                className="image"
                key={currentSlide.id}
                src={currentSlide.imageUrl}
                alt={currentSlide.title}
              />
              <figcaption className="caption">{currentSlide.title}</figcaption>
            </figure>

            <div className="meta" aria-live={isPlaying ? 'off' : 'polite'}>
              Slide {currentIndex + 1} of {totalSlides}
            </div>

            <div className="actions">
              <button type="button" onClick={prev} disabled={!canGoPrev}>
                Previous
              </button>
              <button type="button" onClick={next} disabled={!canGoNext}>
                Next
              </button>
            </div>

            <div className="dots">
              {slides.map((slide, index) => (
                <button
                  key={slide.id}
                  type="button"
                  className={'dot' + (index === currentIndex ? ' dot--active' : '')}
                  onClick={() => goTo(index)}
                  aria-label={`Go to slide ${index + 1}`}
                  aria-current={index === currentIndex ? 'true' : undefined}
                />
              ))}
            </div>
          </div>
        ) : (
          <p className="empty-state">No slides left</p>
        )}

        <div className="tools">
          <button
            type="button"
            className="autoplay-toggle"
            onClick={() => setPlayRequested(!isPlaying)}
            disabled={!canPlay}
          >
            {isPlaying ? 'Pause' : 'Play'}
          </button>
          {currentSlide && (
            <button type="button" className="remove-slide" onClick={removeCurrent}>
              Remove slide
            </button>
          )}
        </div>
      </section>
    </main>
  );
}

