:root {
  color-scheme: dark;
}

html, body {
  margin: 0;
  height: 100%;
  background: #0a0a0a;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
}

.main {
  min-height: 100vh;
  background: #0a0a0a;
  color: #e5e7eb;
  display: grid;
  place-items: center;
  padding: 24px;
}

.section {
  width: 100%;
  max-width: 520px;
  display: grid;
  gap: 16px;
}

h1 {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
}

.frame {
  margin: 0;
  border-radius: 12px;
  overflow: hidden;
  border: 1px solid #1f2937;
  background: #020617;
}

.image {
  display: block;
  width: 100%;
  height: 240px;
  object-fit: cover;
}

.caption {
  padding: 8px 12px;
  font-size: 14px;
  color: #e5e7eb;
  background: rgba(15,23,42,.9);
}

.meta {
  font-size: 12px;
  color: #9ca3af;
  text-align: center;
}

.actions {
  display: flex;
  gap: 8px;
  justify-content: center;
  margin-top: 4px;
}

button {
  background: #a3e635;
  color: #111;
  border: none;
  border-radius: 10px;
  padding: 10px 14px;
  font-weight: 700;
  cursor: pointer;
}

button[disabled] {
  opacity: .5;
  cursor: not-allowed;
}

.dots {
  display: flex;
  justify-content: center;
  gap: 6px;
  margin-top: 6px;
}

.dot {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  border: none;
  background: #374151;
  cursor: pointer;
  padding: 0;
}

.dot.dot--active {
  background: #a3e635;
}

.section:focus-visible {
  outline: 2px solid #a3e635;
  outline-offset: 6px;
  border-radius: 4px;
}

.slider-body {
  display: grid;
  gap: 16px;
}

.tools {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
}

.tools button {
  background: transparent;
  color: #e5e7eb;
  border: 1px solid #374151;
}

.empty-state {
  margin: 0;
  padding: 24px 12px;
  border: 1px dashed #374151;
  border-radius: 12px;
  color: #9ca3af;
  text-align: center;
}
